package com.studio.ai;
import android.content.Context;import android.graphics.Bitmap;import android.media.MediaMetadataRetriever;import android.net.Uri;import org.json.*;import java.util.*;
public final class VideoInspector{
 public interface Progress{void onProgress(int percent,String stage);}private VideoInspector(){}
 public static JSONObject inspect(Context c,Uri u)throws Exception{return inspect(c,u,null);}
 public static JSONObject inspect(Context context,Uri uri,Progress progress)throws Exception{MediaMetadataRetriever r=new MediaMetadataRetriever();try{notify(progress,2,"قراءة معلومات الفيديو");r.setDataSource(context,uri);JSONObject out=new JSONObject();long duration=number(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));out.put("durationMs",duration);out.put("width",(int)number(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)));out.put("height",(int)number(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT)));out.put("rotation",(int)number(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION)));out.put("bitrate",number(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_BITRATE)));String mime=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_MIMETYPE),fps=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_CAPTURE_FRAMERATE);out.put("mime",mime==null?"":mime);out.put("fps",fps==null?"":fps);out.put("hasAudio","yes".equalsIgnoreCase(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO)));out.put("hasVideo","yes".equalsIgnoreCase(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_VIDEO)));out.put("inspectedAt",System.currentTimeMillis());VisualResult v=analyze(r,duration,progress);out.put("samples",v.samples);out.put("visualTimeline",v.timeline);out.put("cutCandidates",v.cuts);out.put("segments",v.segments);out.put("averageChange",v.avgChange);out.put("averageMotion",v.avgMotion);out.put("cutThreshold",v.threshold);out.put("analysisStepMs",v.step);out.put("analysisVersion",5);notify(progress,94,"بناء بصمة المونتاج");out.put("editingStyle",EditingStyleAnalyzer.analyze(out));notify(progress,100,"اكتمل التحليل");return out;}finally{try{r.release();}catch(Exception ignored){}}}
 private static VisualResult analyze(MediaMetadataRetriever r,long duration,Progress progress)throws Exception{VisualResult z=new VisualResult();if(duration<=0)return z;long step=Math.min(1500,Math.max(350,duration/140));z.step=step;List<F> fs=new ArrayList<>();long total=Math.max(1,(duration+step-1)/step),done=0;for(long t=0;t<duration;t+=step){Bitmap b=null;try{b=r.getFrameAtTime(t*1000,MediaMetadataRetriever.OPTION_CLOSEST);if(b!=null){F f=vector(b,t);fs.add(f);JSONObject s=new JSONObject();s.put("timeMs",t);s.put("brightness",f.bri);s.put("colorRange",f.range);z.samples.put(s);}}finally{if(b!=null&&!b.isRecycled())b.recycle();done++;notify(progress,5+(int)(done*70/total),"استخراج وتحليل الإطارات");}}notify(progress,78,"قياس الحركة والتغير");double[] scores=new double[Math.max(0,fs.size()-1)];double sc=0,sm=0;for(int i=0;i<fs.size();i++){F f=fs.get(i);double change=0,motion=0;if(i>0){F p=fs.get(i-1);motion=mad(p.luma,f.luma);double hist=hd(p.hist,f.hist),bj=Math.abs(f.bri-p.bri);change=clamp(motion*.58+hist*.32+bj*.10,0,100);scores[i-1]=change;sc+=change;sm+=motion;}JSONObject q=new JSONObject();q.put("timeMs",f.time);q.put("brightness",f.bri);q.put("colorRange",f.range);q.put("motion",r1(motion));q.put("change",r1(change));z.timeline.put(q);}notify(progress,86,"اكتشاف القصات والمشاهد");double mean=scores.length==0?0:sc/scores.length,var=0;for(double x:scores)var+=(x-mean)*(x-mean);double std=scores.length==0?0:Math.sqrt(var/scores.length);double th=Math.max(26,Math.min(62,mean+1.55*std));long last=-5000;for(int i=0;i<scores.length;i++){long time=fs.get(i+1).time;if(scores[i]>=th&&time-last>=Math.max(500,step)){JSONObject c=new JSONObject();c.put("timeMs",time);c.put("score",r1(scores[i]));c.put("confidence",scores[i]>=th+16?"high":scores[i]>=th+7?"medium":"low");z.cuts.put(c);last=time;}}long start=0;for(int i=0;i<z.cuts.length();i++){long end=z.cuts.getJSONObject(i).getLong("timeMs");if(end>start)z.segments.put(seg(start,end));start=end;}if(duration>start)z.segments.put(seg(start,duration));z.avgChange=r1(scores.length==0?0:sc/scores.length);z.avgMotion=r1(scores.length==0?0:sm/scores.length);z.threshold=r1(th);return z;}
 private static void notify(Progress p,int n,String s){if(p!=null)p.onProgress(Math.max(0,Math.min(100,n)),s);}private static JSONObject seg(long a,long b)throws Exception{JSONObject o=new JSONObject();o.put("startMs",a);o.put("endMs",b);o.put("durationMs",Math.max(0,b-a));return o;}private static F vector(Bitmap source,long t){Bitmap b=Bitmap.createScaledBitmap(source,32,18,true);int n=b.getWidth()*b.getHeight();int[]p=new int[n];b.getPixels(p,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());b.recycle();F f=new F();f.time=t;f.luma=new int[n];f.hist=new int[16];long l=0,rg=0;for(int i=0;i<n;i++){int c=p[i],rr=(c>>16)&255,g=(c>>8)&255,bl=c&255,y=(299*rr+587*g+114*bl)/1000;f.luma[i]=y;f.hist[Math.min(15,y/16)]++;l+=y;rg+=Math.max(rr,Math.max(g,bl))-Math.min(rr,Math.min(g,bl));}f.bri=n==0?0:(int)(l/n);f.range=n==0?0:(int)(rg/n);return f;}private static double mad(int[]a,int[]b){if(a==null||b==null||a.length==0||a.length!=b.length)return 0;long s=0;for(int i=0;i<a.length;i++)s+=Math.abs(a[i]-b[i]);return(s/(double)a.length)*100/255;}private static double hd(int[]a,int[]b){int ta=0,tb=0;for(int v:a)ta+=v;for(int v:b)tb+=v;if(ta==0||tb==0)return 0;double d=0;for(int i=0;i<a.length;i++)d+=Math.abs(a[i]/(double)ta-b[i]/(double)tb);return Math.min(100,d*50);}private static double clamp(double v,double a,double b){return Math.max(a,Math.min(b,v));}private static double r1(double v){return Math.round(v*10)/10.0;}private static long number(String s){try{return s==null?0:Long.parseLong(s);}catch(Exception e){return 0;}}private static final class F{long time;int bri,range;int[]luma,hist;}private static final class VisualResult{JSONArray samples=new JSONArray(),timeline=new JSONArray(),cuts=new JSONArray(),segments=new JSONArray();double avgChange,avgMotion,threshold;long step;}
}
